import datetime
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
DN = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
D = datetime.date
TD = datetime.timedelta
def isbiz(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def sp(d):
    return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + TD(days=1)
    while not isbiz(x):
        x = x + TD(days=1)
    return x
def nth_biz_after(d, n):
    x = d
    k = 0
    while k < n:
        x = x + TD(days=1)
        if isbiz(x):
            k += 1
    return x

import json
try:
    b = config.get('body')
    if isinstance(b, dict):
        ids = [s for s in str(vars.get('product_ids') or '').split(',') if s]
        pid = str(b.get('product_id') or '').strip()
        if pid not in ids and ids:
            low = pid.lower()
            for k, s in enumerate(ids):
                if low in (str(k + 1), 'product ' + str(k + 1), s.lower()):
                    pid = s
        b['product_id'] = pid
        dls = json.loads(str(vars.get('deadlines_json') or '') or 'null') or dict()
        dlv = dls.get(pid)
        ds = str(b.get('date') or '')[:10]
        if dlv and len(ds) == 10:
            d = D.fromisoformat(ds)
            dd = D.fromisoformat(dlv)
            if d > dd:
                d = dd
            elif not isbiz(d):
                nb = nextbiz(d)
                d = nb if nb <= dd else dd
            b['date'] = d.isoformat()
        lim = (json.loads(str(vars.get('limits_json') or '') or 'null') or dict()).get(pid)
        try:
            amt = float(str(b.get('amount')).replace(',', ''))
            if lim and amt > float(lim[1]):
                amt = float(lim[1])
            b['amount'] = round(amt, 2)
        except Exception:
            pass
        vars['cp_last_pid'] = pid
        config['body'] = b
except Exception:
    pass

